// Static source read once per process; no network, SQL or provider call.
const NATALIE_SOURCE=readFileSync(new URL('../../index.html',import.meta.url),'utf8');
const USER_PANEL_SUBMISSION_ENABLED = process.env.AD507_COMMERCIAL_WORKFLOW_ENABLED === 'true';
// Admin creation uses the same form and follows the explicit commercial release switch.
const ADMIN_CREATION_ENABLED = process.env.AD507_COMMERCIAL_WORKFLOW_ENABLED === 'true';
const reads = new Map<string, { start: number; count: number }>();
function allowPanelRead(userId: string) {
  const now = Date.now();
  for (const [key, value] of reads) if (now - value.start >= 60_000) reads.delete(key);
  const entry = reads.get(userId);
  if (entry) return ++entry.count <= 60;
  if (reads.size >= 1024) return false;
  reads.set(userId, { start: now, count: 1 });
  return true;
}
// Canonical Google identity and ownership only. This panel never activates Residential OWNER.
export async function userPanelData(sql: Sql, user: { id: string; roles: string[] }, params=new URLSearchParams()) {
  const addressPage=await adminAddressPage(sql,params,'addresses',user.id);
  const addresses=addressPage.items;
  const orders = await sql.unsafe(`SELECT id::text,status,currency,amount_cents AS "amountCents",created_at AS "createdAt" FROM ad507.orders WHERE user_id=$1::uuid ORDER BY created_at DESC,id LIMIT 100`, [user.id]);
  const plans = await sql.unsafe(`SELECT code,name FROM ad507.plans WHERE status='ACTIVE' ORDER BY code`);
  return { addresses, nextAddressCursor:addressPage.nextCursor, orders, plans, actions: { prepareRequest: user.roles.includes('CLIENT') || user.roles.includes('ADMIN'), submitRequest: USER_PANEL_SUBMISSION_ENABLED && (user.roles.includes('CLIENT') || user.roles.includes('ADMIN')), checkout: false } };
}
export async function handleUserPanel(req: Request, sql: Sql, auth: ReturnType<typeof createGeneralAuth>): Promise<Response | null> {
  const url = new URL(req.url);
  if (!['/v1/user/panel','/v1/user/requests','/panel','/panel/','/commercial/panama','/commercial/international'].includes(url.pathname)) return null;
  if (url.pathname === '/v1/user/requests') {
    // No dormant writer: submissions require a separately reviewed implementation.
    return Response.json({ ok: false, error: 'USER_PANEL_SUBMISSION_NOT_ENABLED' }, { status: 503, headers: { 'cache-control': 'no-store', 'x-content-type-options': 'nosniff' } });
  }
  // Render the account panel even without a session; its login view handles authentication.
  if (req.method !== 'GET') return Response.json({ ok: false, error: 'METHOD_NOT_ALLOWED' }, { status: 405, headers: { 'cache-control': 'no-store' } });
  if (url.pathname !== '/v1/user/panel') {
    const nonce = crypto.randomUUID().replaceAll('-', '');
    return new Response((url.pathname.startsWith('/commercial/')?commercialEntryHtml(url.pathname.endsWith('international'),url):userPanelPresentation(url)).replace("location.replace('https://direcciones.lat/')",url.hostname==='direcciones.lat'?"location.replace('/')":"location.replace('https://direcciones507.com/')").replaceAll('<script>', '<script nonce="' + nonce + '">'), { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store', 'content-security-policy': "default-src 'self'; img-src 'self' https: blob:; style-src 'unsafe-inline'; script-src 'nonce-" + nonce + "'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'; object-src 'none'; connect-src 'self'"+(url.pathname.startsWith('/commercial/')?' https://ad507-core-production.up.railway.app':'')+" https://*.google-analytics.com https://*.analytics.google.com", 'referrer-policy': 'no-referrer', 'x-content-type-options': 'nosniff', 'x-robots-tag': 'noindex, nofollow' } });
  }
  let foreignOrigin = req.headers.get('sec-fetch-site') === 'cross-site';
  try { if (req.headers.has('origin') && new URL(req.headers.get('origin')!).host !== url.host) foreignOrigin = true; } catch { foreignOrigin = true; }
  if (foreignOrigin) return Response.json({ ok: false, error: 'ORIGIN_DENIED' }, { status: 403, headers: { 'cache-control': 'no-store' } });
  try {
    const user = await auth.currentUser(req);
    if (!user) return Response.json({ ok: false, error: 'UNAUTHENTICATED' }, { status: 401, headers: { 'cache-control': 'no-store' } });
    if (!user.roles.some(r => ['CLIENT','ADMIN','OPERATOR'].includes(String(r)))) return Response.json({ ok: false, error: 'FORBIDDEN' }, { status: 403, headers: { 'cache-control': 'no-store' } });
    if (!allowPanelRead(user.id)) return Response.json({ ok: false, error: 'RATE_LIMITED' }, { status: 429, headers: { 'cache-control': 'no-store', 'retry-after': '60' } });
    const adminMode=url.searchParams.get('adminCreate')==='1';
    if(adminMode&&!user.roles.includes('ADMIN'))return Response.json({ok:false,error:'FORBIDDEN'},{status:403});
    const data=await userPanelData(sql,user as {id:string;roles:string[]},url.searchParams);
    if(adminMode)data.actions.submitRequest=ADMIN_CREATION_ENABLED && user.roles.includes('ADMIN');
    return Response.json({ ok: true, user: { displayName: user.displayName, email: user.email }, ...data }, { headers: { 'cache-control': 'no-store' } });
  } catch (error) { const dbError=error as {code?:unknown;schema?:unknown;table?:unknown;column?:unknown}; const safe=(v:unknown)=>typeof v==='string'&&/^[A-Za-z0-9_]{1,64}$/.test(v)?v:undefined; console.error(JSON.stringify({event:'user_panel_query_failed',route:'/v1/user/panel',dbCode:safe(dbError?.code),dbSchema:safe(dbError?.schema),dbTable:safe(dbError?.table),dbColumn:safe(dbError?.column)})); return Response.json({ ok: false, error: 'USER_PANEL_UNAVAILABLE' }, { status: 503, headers: { 'cache-control': 'no-store' } }); }
}
export function commercialEntryHtml(international=false,url=new URL(international?'https://direcciones.lat/':'https://direcciones507.com/')){
 const context=commercialEntryContext(url);
 // Reuse the historical widget source, never another conversation implementation.
 const source=NATALIE_SOURCE;
 const styleStart=source.indexOf('/* Natalie: conversación conectada');
 const styleEnd=source.indexOf('</style>',styleStart);
 const widgetStart=source.indexOf('<button id="natalieLauncher"');
 const scriptStart=source.indexOf('<script>',widgetStart);
 const scriptEnd=source.indexOf('</script>',scriptStart);
 if(styleStart<0||styleEnd<0||widgetStart<0||scriptStart<0||scriptEnd<0)throw Error('EXISTING_NATALIE_WIDGET_REQUIRED');
 const widget=source.slice(widgetStart,scriptStart);
 const script=source.slice(scriptStart+8,scriptEnd);
 // Match exact public hosts behind Railway TLS; backend Origin checks remain unchanged.
 const natalieAllowed=nataliePresentationAllowed(url,process.env);
 const html=userPanelHtml.replace(/<title>[^<]*<\/title>/,'<title>'+context.title+'</title><meta name="description" content="'+context.description+'"><meta property="og:type" content="website"><meta property="og:url" content="'+context.canonical+'"><meta property="og:title" content="'+context.title+'"><meta property="og:description" content="'+context.description+'"><meta property="og:image" content="'+(context.international?'https://direcciones507.com/og-latam-2026.png':'https://direcciones507.com/og-507-2026.png')+'"><meta property="og:image:secure_url" content="'+(context.international?'https://direcciones507.com/og-latam-2026.png':'https://direcciones507.com/og-507-2026.png')+'"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="'+context.title+'"><meta name="twitter:description" content="'+context.description+'"><meta name="twitter:image" content="'+(context.international?'https://direcciones507.com/og-latam-2026.png':'https://direcciones507.com/og-507-2026.png')+'"><link rel="canonical" href="'+context.canonical+'">')
 .replace('<div class="brand">Direcciones<span>507</span></div>',context.international?'<div class="brand" style="color:#76aaff">Direcciones LATAM</div>':'<div class="brand">Direcciones<span>507</span></div>')
 .replace('<main>','<main>'+commercialNavigation(context.country,context.international))
 .replace('</main>','<footer class="card" style="color:#0b57d0">'+(context.international?'Direcciones LATAM · Direcciones507, presencia de Panamá':'Direcciones507 · Panamá')+'</footer></main>')
 .replace('<script>','<script>const commercialInitialCountry='+JSON.stringify(context.country)+';')
 .replace('load();\n</script>', 'load();('+initializeCommercialNavigation.toString()+')('+JSON.stringify(COUNTRIES)+');\n</script>')
 .replace('</style>',source.slice(styleStart,styleEnd)+'</style>')
 .replace('</main>','</main>'+(natalieAllowed?widget:widget.replace('id="natalieLauncher"','id="natalieLauncher" disabled title="Natalie pendiente de validación para este dominio"')))
 .replace('</script>',(natalieAllowed?script:'')+'</script>')
 .replace("location.replace('https://direcciones507.com/')",url.hostname==='direcciones.lat'?"location.replace('/')":"location.replace('https://direcciones507.com/')");
 return context.international?latamPresentation(html):html;
}
